require_once __DIR__.'/../includes/auth.php'; require_role('student');$uid=current_user()['id'];$s=$pdo->prepare("SELECT status,COUNT(*) c FROM bookings WHERE student_user_id=? GROUP BY status");$s->execute([$uid]);$stats=['Total Bookings'=>0,'Pending Requests'=>0,'Approved Bookings'=>0,'Rejected Bookings'=>0];foreach($s as $r){$stats['Total Bookings']+=(int)$r['c'];if(isset($stats[$r['status'].' Bookings']))$stats[$r['status'].' Bookings']=(int)$r['c'];if($r['status']==='Pending')$stats['Pending Requests']=(int)$r['c'];}
page_header('Student Dashboard','student');?>
<div class="grid-stats"><?php foreach($stats as $k=>$v):?><div class="card-dark"><div class="stat-label"><?=e($k)?></div><div class="stat"><?=$v?></div></div><?php endforeach?></div><div class="panel"><h2 class="section-title">Quick actions</h2><a class="btn btn-primary me-2" href="equipment.php">Browse equipment</a><a class="btn btn-outline-light" href="my-bookings.php">Track my bookings</a></div><?php page_footer();?>
